def __init__(self, grid_size: np.ndarray, num_obstacles: int=40, obstacle_avoid_points: list[Position]=[], obstacle_arrangement: ObstacleArrangement=ObstacleArrangement.RANDOM, time_limit: int=100):
    self.obstacle_avoid_points = obstacle_avoid_points
    self.time_limit = time_limit
    self.grid_size = grid_size
